sect1.programlisting:
IMPORT STD;

// Check if DST is in effect for July 4th, 2024
SummerDate := 20240704;
IsDSTSummer := STD.Date.IsUSDaylightSavingsInEffect(SummerDate);
      // IsDSTSummer will be TRUE

// Check if DST is in effect for December 25th, 2024  
WinterDate := 20241225;
IsDSTWinter := STD.Date.IsUSDaylightSavingsInEffect(WinterDate);
      // IsDSTWinter will be FALSE

// Check if DST is in effect for today's date
IsTodayDST := STD.Date.IsUSDaylightSavingsInEffect(STD.Date.Today());
      // IsTodayDST contains whether DST is currently in effect
